// Doctor-only evidence view for one case: plain-language overview first, raw trace last.
import { useState } from 'react'

import type { CaseReviewDto } from '../../services/apiClient'
import { reviewReasons, statusLabel, structuredEntries } from './approvalReview'
import { ApprovalSupportingEvidence } from './ApprovalSupportingEvidence'
import { SafetyChecks } from './SafetyChecks'

type TabId = 'overview' | 'evidence' | 'technical'

const tabs: Array<{ id: TabId; label: string }> = [
  { id: 'overview', label: 'Clinical overview' },
  { id: 'evidence', label: 'Clinical evidence' },
  { id: 'technical', label: 'Technical trace' },
]

function EvidenceList({ raw, empty }: { raw?: string | null; empty: string }) {
  const entries = structuredEntries(raw)
  if (entries.length === 0) return <p className="care-caption">{empty}</p>
  return (
    <dl className="approval-facts">
      {entries.map((entry) => (
        <div key={entry.label}>
          <dt>{entry.label}</dt>
          {entry.values.map((value, index) => (
            <dd key={`${entry.label}-${index}`}>{value}</dd>
          ))}
        </div>
      ))}
    </dl>
  )
}

function RawJson({ title, raw }: { title: string; raw?: string | null }) {
  if (!raw) return null
  return (
    <details>
      <summary>{title} — raw doctor-only JSON</summary>
      <pre>{raw}</pre>
    </details>
  )
}

import { IconStethoscope, IconBrain, IconDna } from './ApprovalIcons'

export function ApprovalEvidenceTabs({ review }: { review: CaseReviewDto }) {
  const [tab, setTab] = useState<TabId>('overview')

  return (
    <>
      <div className="approval-tabs" role="tablist" aria-label="Case details">
        {tabs.map((item) => (
          <button
            key={item.id}
            type="button"
            role="tab"
            id={`approval-tab-${item.id}`}
            aria-selected={tab === item.id}
            aria-controls={`approval-panel-${item.id}`}
            className="approval-tab"
            onClick={() => setTab(item.id)}
          >
            {item.label}
          </button>
        ))}
      </div>

      <div role="tabpanel" id={`approval-panel-${tab}`} aria-labelledby={`approval-tab-${tab}`}>
        {tab === 'overview' && (
          <div className="approval-grid">
            <article className="care-panel approval-tile approval-tile--attention">
              <h3><IconStethoscope /> Why this case needs review</h3>
              <ul className="approval-reasons">
                {reviewReasons(review).map((reason) => (
                  <li key={reason}>{reason}</li>
                ))}
              </ul>
            </article>
            <article className="care-panel approval-tile approval-tile--draft">
              <h3><IconBrain /> AI findings — plain language</h3>
              <p className="approval-tag">Unapproved AI draft</p>
              <div className="approval-findings">
                <EvidenceList raw={review.draftAdvisoryJson} empty="No AI draft advisory was produced for this request." />
              </div>
              <p className="care-caption">Not a diagnosis. Not visible to the patient.</p>
            </article>
            <article className="care-panel approval-tile">
              <SafetyChecks traces={review.traces} />
            </article>
            <article className="care-panel approval-tile approval-family">
              <h3><IconDna /> Consented family-history context</h3>
              <EvidenceList
                raw={review.familialRiskJson}
                empty="No consented family-history screening indication is available."
              />
              <p className="care-caption">A screening indication only — never a diagnosis.</p>
            </article>
            <ApprovalSupportingEvidence key={review.id} memberId={review.memberId} caseId={review.id} />
          </div>
        )}

        {tab === 'evidence' && (
          <div className="approval-grid">
            <article className="care-panel approval-tile">
              <h3>Patient context</h3>
              <EvidenceList raw={review.contextJson} empty="No structured context was available for this stage." />
            </article>
            <article className="care-panel approval-tile">
              <h3>Analysis</h3>
              <EvidenceList raw={review.analysisJson} empty="No structured analysis was available for this stage." />
            </article>
          </div>
        )}

        {tab === 'technical' && (
          <article className="care-panel approval-tile">
            <h3>
              Technical audit trace <span className="status-badge status-badge--muted">Internal only</span>
            </h3>
            <p className="care-caption">
              For audit and troubleshooting. Trace steps: {review.traces.length} · Case status:{' '}
              {statusLabel(review.status)}
            </p>
            {review.traces.length > 0 && (
              <div className="table-scroll">
                <table>
                  <thead>
                    <tr>
                      <th scope="col">Step</th>
                      <th scope="col">Agent</th>
                      <th scope="col">Status</th>
                      <th scope="col">Confidence</th>
                      <th scope="col">Latency</th>
                      <th scope="col">Tools denied</th>
                    </tr>
                  </thead>
                  <tbody>
                    {review.traces.map((trace) => (
                      <tr key={trace.stepNumber}>
                        <td>{trace.stepNumber}</td>
                        <td>{statusLabel(trace.agent)}</td>
                        <td>{statusLabel(trace.status)}</td>
                        <td>{Math.round(trace.confidence * 100)}%</td>
                        <td>{trace.latencyMilliseconds} ms</td>
                        <td>{trace.toolsDenied.length}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <div className="approval-raw">
              <RawJson title="Context" raw={review.contextJson} />
              <RawJson title="Analysis" raw={review.analysisJson} />
              <RawJson title="Familial risk" raw={review.familialRiskJson} />
              <RawJson title="Draft advisory" raw={review.draftAdvisoryJson} />
            </div>
          </article>
        )}
      </div>
    </>
  )
}
